#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define MAX_CHUNKS 64
#define CHUNK_HDR_SIZE 8

typedef struct {
    uint16_t chunk_type;
    uint16_t flags;
    uint32_t data_length;
} __attribute__((packed)) ChunkHeader;

typedef struct {
    unsigned char *buffer;
    size_t buf_size;
    size_t write_pos;
} OutputBuffer;

typedef struct {
    const unsigned char *data;
    size_t total_len;
    size_t read_pos;
} InputStream;

// Security: validate chunk header fields
static int validate_chunk(const ChunkHeader *hdr, size_t remaining) {
    // Reject chunks claiming more data than available
    if (hdr->data_length > remaining) {
        return 0;
    }
    // Reject unknown chunk types
    if (hdr->chunk_type > 0x0F) {
        return 0;
    }
    return 1;
}

// Compute required output size for a chunk transformation
// Type 0x01: raw copy
// Type 0x02: RLE decode (first 2 bytes = count + byte)
// Type 0x03: duplicate chunk data N times (flags = N, max 4)
static int compute_output_size(const ChunkHeader *hdr, const unsigned char *chunk_data, size_t *out_size) {
    switch (hdr->chunk_type) {
        case 0x01:
            *out_size = hdr->data_length;
            return 1;
        case 0x02:
            if (hdr->data_length < 2) return 0;
            *out_size = (size_t)chunk_data[0];
            return 1;
        case 0x03: {
            uint16_t repeat = hdr->flags;
            if (repeat == 0 || repeat > 4) return 0;
            *out_size = (size_t)hdr->data_length * repeat;
            return 1;
        }
        default:
            *out_size = 0;
            return 1;
    }
}

// Safe buffer space check
static int has_space(const OutputBuffer *ob, size_t needed) {
    if (needed == 0) return 1;
    size_t available = ob->buf_size - ob->write_pos;
    return available >= needed;
}

// Process a single chunk and write to output
static int process_chunk(const ChunkHeader *hdr, const unsigned char *chunk_data,
                         OutputBuffer *ob) {
    size_t needed;
    if (!compute_output_size(hdr, chunk_data, &needed)) {
        return 0;
    }
    if (!has_space(ob, needed)) {
        return 0;
    }

    switch (hdr->chunk_type) {
        case 0x01:
            memcpy(ob->buffer + ob->write_pos, chunk_data, hdr->data_length);
            ob->write_pos += hdr->data_length;
            break;
        case 0x02: {
            size_t count = chunk_data[0];
            unsigned char val = chunk_data[1];
            memset(ob->buffer + ob->write_pos, val, count);
            ob->write_pos += count;
            break;
        }
        case 0x03: {
            uint16_t repeat = hdr->flags;
            for (uint16_t i = 0; i < repeat; i++) {
                memcpy(ob->buffer + ob->write_pos, chunk_data, hdr->data_length);
                ob->write_pos += hdr->data_length;
            }
            break;
        }
        default:
            break;
    }
    return 1;
}

// Main parsing function: processes a chunked binary format
// Returns allocated buffer with decoded content, or NULL on error
unsigned char* decode_chunked_stream(const unsigned char *input, size_t input_len,
                                      size_t *output_len) {
    if (!input || input_len < CHUNK_HDR_SIZE || !output_len) {
        return NULL;
    }

    // First pass: compute total output size needed
    size_t total_output = 0;
    size_t pos = 0;
    int chunk_count = 0;

    while (pos + CHUNK_HDR_SIZE <= input_len && chunk_count < MAX_CHUNKS) {
        const ChunkHeader *hdr = (const ChunkHeader *)(input + pos);
        size_t remaining = input_len - pos - CHUNK_HDR_SIZE;

        if (!validate_chunk(hdr, remaining)) {
            return NULL;
        }

        const unsigned char *chunk_data = input + pos + CHUNK_HDR_SIZE;
        size_t chunk_output;
        if (!compute_output_size(hdr, chunk_data, &chunk_output)) {
            return NULL;
        }

        // Accumulate total with overflow check
        if (total_output + chunk_output < total_output) {
            return NULL; // overflow
        }
        total_output += chunk_output;

        pos += CHUNK_HDR_SIZE + hdr->data_length;
        chunk_count++;
    }

    if (total_output == 0 || total_output > 10 * 1024 * 1024) {
        return NULL;
    }

    // Allocate output buffer
    unsigned char *output = (unsigned char *)malloc(total_output);
    if (!output) return NULL;

    OutputBuffer ob = { .buffer = output, .buf_size = total_output, .write_pos = 0 };

    // Second pass: decode chunks
    pos = 0;
    chunk_count = 0;
    while (pos + CHUNK_HDR_SIZE <= input_len && chunk_count < MAX_CHUNKS) {
        const ChunkHeader *hdr = (const ChunkHeader *)(input + pos);
        const unsigned char *chunk_data = input + pos + CHUNK_HDR_SIZE;

        if (!process_chunk(hdr, chunk_data, &ob)) {
            free(output);
            return NULL;
        }

        pos += CHUNK_HDR_SIZE + hdr->data_length;
        chunk_count++;
    }

    *output_len = ob.write_pos;
    return output;
}

// Demonstration
int main(int argc, char **argv) {
    // Read from file if provided, otherwise use test data
    if (argc > 1) {
        FILE *f = fopen(argv[1], "rb");
        if (!f) { perror("fopen"); return 1; }
        fseek(f, 0, SEEK_END);
        long fsize = ftell(f);
        fseek(f, 0, SEEK_SET);
        if (fsize <= 0 || fsize > 1024*1024) { fclose(f); return 1; }
        unsigned char *data = malloc(fsize);
        if (!data) { fclose(f); return 1; }
        fread(data, 1, fsize, f);
        fclose(f);

        size_t out_len = 0;
        unsigned char *result = decode_chunked_stream(data, (size_t)fsize, &out_len);
        if (result) {
            printf("Decoded %zu bytes\n", out_len);
            free(result);
        } else {
            printf("Decode failed\n");
        }
        free(data);
    } else {
        // Test: type 0x03 chunk with data_length=0xFFFF and flags(repeat)=4
        // compute_output_size: 0xFFFF * 4 = 0x3FFFC (ok, fits in size_t)
        // But what about uint32_t data_length with uint16_t repeat?
        unsigned char test[] = {
            0x01, 0x00,  // chunk_type = 0x01 (raw copy)
            0x00, 0x00,  // flags = 0
            0x05, 0x00, 0x00, 0x00,  // data_length = 5
            'H', 'e', 'l', 'l', 'o'  // data
        };
        size_t out_len = 0;
        unsigned char *result = decode_chunked_stream(test, sizeof(test), &out_len);
        if (result) {
            printf("Decoded: %.*s\n", (int)out_len, result);
            free(result);
        }
    }
    return 0;
}
